export async function signIn(page, email, password) {
    await page.getByRole("textbox", { name: "Email" }).fill(email);
    await page.getByRole("textbox", { name: "Password" }).fill(password);
    // Wait to finish any potential hydration
    await page.waitForTimeout(1500);
    const responsePromise = page.waitForResponse("**/auth/login**");
    await page.getByRole("button", { name: "Sign In" }).click();
    const response = await responsePromise;

    // Wait for network activities to finish
    await page.waitForTimeout(3000);

    return response;
}

export async function selectAllItemsAndOpenBatchEditor(page) {
    await page.getByRole("row", { name: "check_box_outline_blank Name" }).getByRole("checkbox").click();
    await page.getByRole("button", { name: "edit" }).click();
}

export async function enableBatchFieldAndSubmit(page, fieldIndex, value) {
    await page.getByRole("checkbox", { name: "check_box_outline_blank" }).nth(fieldIndex).click();
    await page.getByRole("textbox").nth(2).fill(value);
    // Wait to finish any potential hydration
    await page.waitForTimeout(1500);
    const responsePromise = page.waitForResponse("**/items/**/**");
    await page.getByRole("button", { exact: true, name: "check" }).click();
    const response = await responsePromise;

    // Wait for network activities to finish
    await page.waitForTimeout(3000);

    return response;
}

export async function selectItemRowAndOpenBatchEditor(page, rowIndex) {
    await page.locator("tr").nth(rowIndex).locator("i").click();
    await page.getByRole("button", { name: "edit" }).click();
}
